
/**
 * CricZone Phase 25.7.7
 * Consolidated consistency evidence validation.
 *
 * Consumes four reports generated by the same
 * GitHub Actions workflow run.
 *
 * Does not read previous workflow artifacts.
 */

import fs from "node:fs";
import path from "node:path";

const directory = path.resolve(
  "benchmarks/resilience/consistency/reports"
);

const definitions = [
  {
    phase: "25.7.6.1",
    name: "PostgreSQL and Valkey",
    file: "cache-recovery.json",
    flags: [
      "authoritativeDatabasePreserved",
      "staleCacheNeverServed",
      "failedWorkerRollbackConfirmed",
      "pendingOutboxRetained",
      "retryCompleted",
      "cacheRepaired",
      "duplicateOutboxRejected",
      "secondUpdateConsistent"
    ],
    check: r =>
      r.finalVersion === 3 &&
      r.finalRuns === 110
  },
  {
    phase: "25.7.6.2",
    name: "Kafka replay",
    file: "kafka-replay.json",
    flags: [
      "originalEventsApplied",
      "duplicateEventIdsSkipped",
      "duplicateDeliveryIdsRejected",
      "consumerRestarted",
      "replayDidNotDoubleScore",
      "newEventAfterRestartApplied",
      "authoritativeScoreVerified",
      "noUnexpectedDeadLetters"
    ],
    check: r =>
      r.publishedEvents === 9 &&
      r.handlerInvocations === 5 &&
      r.uniqueDeliveries === 3 &&
      r.redisDuplicateSkips >= 4 &&
      r.postgresDuplicateRejections >= 2 &&
      r.finalRuns === 12 &&
      r.finalWickets === 1
  },
  {
    phase: "25.7.6.3",
    name: "WebSocket REST recovery",
    file: "websocket-resync.json",
    flags: [
      "baselineDelivered",
      "disconnectConfirmed",
      "missedEventsConfirmed",
      "authoritativeDatabasePreserved",
      "clientReconnected",
      "roomSubscriptionRestored",
      "restSnapshotRecovered",
      "newLiveEventDelivered",
      "staleEventRejected",
      "finalStateConsistent"
    ],
    check: r =>
      r.missedEventCount === 2 &&
      r.staleEventsIgnored >= 1 &&
      r.finalScore?.version === 5 &&
      r.finalScore?.runs === 22 &&
      r.finalScore?.wickets === 1
  },
  {
    phase: "25.7.6.4",
    name: "Cross-component consistency",
    file: "cross-component.json",
    flags: [
      "kafkaProcessed",
      "duplicateEventIdSkipped",
      "duplicateDeliveryRejected",
      "postgresAuthoritative",
      "staleRedisBypassed",
      "pendingInvalidationRetained",
      "cacheRepaired",
      "websocketMissedDuringDisconnect",
      "restResynchronizationSucceeded",
      "newLiveEventDelivered",
      "staleWebsocketEventRejected",
      "finalComponentsConsistent"
    ],
    check: r =>
      r.publishedEvents === 5 &&
      r.successfulMessages === 4 &&
      r.duplicateEventSkips === 1 &&
      r.duplicateDeliveryRejections === 1 &&
      r.uniqueDeliveries === 3 &&
      r.missedEvents === 1 &&
      r.staleEventsIgnored >= 1 &&
      r.finalScore?.version === 4 &&
      r.finalScore?.runs === 22 &&
      r.finalScore?.wickets === 1
  }
];

const report = {
  phase: "25.7.7",
  scenario: "consolidated_resilience_consistency",
  workflowRunId: process.env.GITHUB_RUN_ID ?? null,
  commitSha: process.env.GITHUB_SHA ?? null,
  repository: process.env.GITHUB_REPOSITORY ?? null,
  matrixResult: process.env.MATRIX_RESULT ?? null,
  generatedAt: new Date().toISOString(),
  totalScenarios: definitions.length,
  passedScenarios: 0,
  failedScenarios: 0,
  scenarios: {},
  failures: [],
  warnings: [
    "This report covers Phase 25.7.6.1 through 25.7.6.4.",
    "All reports originate from this consolidated workflow run.",
    "The benchmarks execute isolated integration scenarios.",
    "Production frontend recovery and full cricket-schema consistency are not established.",
    "Phase 25.7.1 through 25.7.5 historical evidence is outside this report."
  ],
  passed: false
};

function validateScenario(definition) {
  const filePath = path.join(
    directory,
    definition.file
  );

  const result = {
    phase: definition.phase,
    name: definition.name,
    file: definition.file,
    runId: null,
    passed: false,
    failures: [],
    warnings: []
  };

  try {
    if (!fs.existsSync(filePath)) {
      throw new Error(
        `Missing source report: ${definition.file}`
      );
    }

    const source = JSON.parse(
      fs.readFileSync(filePath, "utf8")
    );

    result.runId = source.runId ?? null;

    if (source.phase !== definition.phase) {
      result.failures.push(
        `Incorrect phase: ${source.phase}`
      );
    }

    if (source.isolated !== true) {
      result.failures.push(
        "Isolation verification missing"
      );
    }

    if (source.passed !== true) {
      result.failures.push(
        "Source benchmark did not pass"
      );
    }

    if (
      !Array.isArray(source.failures) ||
      source.failures.length !== 0
    ) {
      result.failures.push(
        "Source report contains failures"
      );
    }

    if (
      typeof source.runId !== "string" ||
      !/^[0-9a-f-]{36}$/i.test(source.runId)
    ) {
      result.failures.push(
        "Missing or invalid benchmark run ID"
      );
    }

    for (const flag of definition.flags) {
      if (source[flag] !== true) {
        result.failures.push(
          `Required check failed: ${flag}`
        );
      }
    }

    if (!definition.check(source)) {
      result.failures.push(
        "Scenario metric reconciliation failed"
      );
    }

    result.warnings = Array.isArray(source.warnings)
      ? source.warnings
      : [];

    result.passed =
      result.failures.length === 0;

  } catch (error) {
    result.failures.push(error.message);
  }

  return result;
}

for (const definition of definitions) {
  const result = validateScenario(definition);

  report.scenarios[definition.phase] = result;

  if (result.passed) {
    report.passedScenarios++;
  } else {
    report.failedScenarios++;

    for (const failure of result.failures) {
      report.failures.push(
        `${definition.phase}: ${failure}`
      );
    }
  }
}

if (report.matrixResult !== "success") {
  report.failures.push(
    `Benchmark matrix result: ${report.matrixResult ?? "missing"}`
  );
}

if (
  !report.workflowRunId ||
  !report.commitSha ||
  !report.repository
) {
  report.failures.push(
    "Missing GitHub Actions execution provenance"
  );
}

report.passed =
  report.passedScenarios === report.totalScenarios &&
  report.failures.length === 0;

const markdown = [
  "# CricZone Phase 25.7.7: Consolidated Resilience Consistency",
  "",
  `**Status:** ${report.passed ? "PASS" : "FAIL"}`,
  "",
  `**Workflow run:** ${report.workflowRunId ?? "Unknown"}`,
  "",
  `**Commit:** ${report.commitSha ?? "Unknown"}`,
  "",
  `**Benchmark matrix:** ${report.matrixResult ?? "Unknown"}`,
  "",
  "| Phase | Scenario | Result |",
  "|---|---|---|",
  ...Object.values(report.scenarios).map(s =>
    `| ${s.phase} | ${s.name} | ${s.passed ? "PASS" : "FAIL"} |`
  ),
  "",
  `**Passed:** ${report.passedScenarios}/${report.totalScenarios}`,
  "",
  "## Failures",
  "",
  ...(report.failures.length
    ? report.failures.map(f => `- ${f}`)
    : ["None"]),
  "",
  "## Scope and limitations",
  "",
  ...report.warnings.map(w => `- ${w}`),
  ""
].join("\n");

fs.mkdirSync(directory, {
  recursive: true
});

fs.writeFileSync(
  path.join(directory, "consolidated.json"),
  JSON.stringify(report, null, 2) + "\n"
);

fs.writeFileSync(
  path.join(directory, "consolidated.md"),
  markdown
);

console.log(markdown);

if (!report.passed) {
  process.exitCode = 1;
}
